mapper.select:
select

from suning_withhold_apply
where case_id = #{caseId,jdbcType=BIGINT} and case_no = #{caseNo,jdbcType=VARCHAR}

    and withhold_state = #{withholdState,jdbcType=INTEGER}

select
count(1)
from suning_withhold_apply swa
left join case_center_info cci on swa.case_id = cci.id


        and swa.case_id = #{caseId,jdbcType=BIGINT}


        and swa.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')


        and swa.case_title like concat('%',#{caseTitle,jdbcType=VARCHAR},'%')


        and swa.withhold_money = #{withholdMoney,jdbcType=DOUBLE}


        and swa.withhold_time = #{withholdTime,jdbcType=TIMESTAMP}


        and swa.withhold_state = #{withholdState,jdbcType=INTEGER}


        and swa.withhold_type = #{withholdType,jdbcType=INTEGER}


        and swa.app_user_id = #{appUserId,jdbcType=BIGINT}


        and swa.code = #{code,jdbcType=VARCHAR}


        and swa.remark like concat('%',#{remark,jdbcType=VARCHAR},'%')


        and swa.account_state = #{accountState,jdbcType=INTEGER}



            and swa.apply_type in (0,2)


            and swa.apply_type in (1,2,4)



        and swa.order_code like concat('%',#{orderCode,jdbcType=VARCHAR},'%')


        and swa.trade_code like concat('%',#{tradeCode,jdbcType=VARCHAR},'%')


        and (swa.account_state is null or swa.account_state != 1)  and swa.withhold_state = 2


        and swa.withhold_money > 0


        and (swa.account_state =0 or swa.account_state is null )



            and (cci.is_test_case = #{isTestcase,jdbcType=INTEGER} and cci.delete_flag !=1 or swa.case_id is null)




            and (cci.is_test_case = 0 and cci.delete_flag !=1 or swa.case_id is null)


            and (cci.is_test_case = 1 and cci.delete_flag !=1 or swa.case_id is null)

select
swa.id as id, swa.case_id as caseId, swa.case_no as caseNo, swa.case_title as caseTitle, swa.withhold_money as withholdMoney,
swa.withhold_time as withholdTime, swa.withhold_state as withholdState, swa.withhold_type as withholdType,
swa.app_user_id as appUserId, swa.code as code, swa.remark as remark,swa.account_state as accountState,
swa.apply_type as applyType, swa.order_code as orderCode,swa.trade_code as tradeCode
from suning_withhold_apply swa
left join case_center_info cci on swa.case_id = cci.id


        and swa.case_id = #{caseId,jdbcType=BIGINT}


        and swa.case_no like concat('%',#{caseNo,jdbcType=VARCHAR},'%')


        and swa.case_title like concat('%',#{caseTitle,jdbcType=VARCHAR},'%')


        and swa.withhold_money = #{withholdMoney,jdbcType=DOUBLE}


        and swa.withhold_time = #{withholdTime,jdbcType=TIMESTAMP}


        and swa.withhold_state = #{withholdState,jdbcType=INTEGER}


        and swa.withhold_type = #{withholdType,jdbcType=INTEGER}


        and swa.app_user_id = #{appUserId,jdbcType=BIGINT}


        and swa.code = #{code,jdbcType=VARCHAR}


        and swa.remark like concat('%',#{remark,jdbcType=VARCHAR},'%')


        and swa.account_state = #{accountState,jdbcType=INTEGER}



            and swa.apply_type in (0,2)


            and swa.apply_type in (1,2,4)



        and swa.order_code like concat('%',#{orderCode,jdbcType=VARCHAR},'%')


        and swa.trade_code like concat('%',#{tradeCode,jdbcType=VARCHAR},'%')


        and (swa.account_state is null or swa.account_state != 1)  and swa.withhold_state = 2


        and swa.withhold_money > 0


        and (swa.account_state =0 or swa.account_state is null )



            and (cci.is_test_case = #{isTestcase,jdbcType=INTEGER} and cci.delete_flag !=1 or swa.case_id is null)




            and (cci.is_test_case = 0 and cci.delete_flag !=1 or swa.case_id is null)


            and (cci.is_test_case = 1 and cci.delete_flag !=1 or swa.case_id is null)



order by swa.id desc limit #{pageIndex} , #{pageSize}
